mapper.select:
/* 관리자 (코드관리:그룹) 조회 쿼리 (searchGropCode)*/ select CD_GROUP as cdGroup ,CD_GROUP_NM as cdGroupNm ,LAST_CHNG_EMPNO as lastChngEmpno from ocuoc_ccgrp_m where 1=1
and CD_GROUP like '%'||#{cdGroup}||'%'
and CD_GROUP_NM like '%'||#{cdGroupNm}||'%'

mapper.insert:
/* 관리자 (코드관리:그룹) 저장 쿼리 (insertGroupCode)*/
INSERT INTO ocuoc_ccgrp_m
( CD_GROUP
, CD_GROUP_NM
, LAST_CHNG_EMPNO
, LAST_CHNG_DTTM
, FRST_REG_EMPNO
, FRST_REG_DTTM
)
VALUES (
		 #{cdGroup}
	   , #{cdGroupNm}
	   , #{lastChngEmpno}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   , #{lastChngEmpno}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   )

/* 관리자 (코드관리:상세) 저장 쿼리 (insertGroupDetail)*/
INSERT INTO ocuoc_ccdtl_l
( CD_GROUP
, CD_VAL
, CD_NM
, CD_DESC
, LNUP_SER
, UZ_YN
, VLD_STDD
, VLD_ENDT
, LAST_CHNG_EMPNO
, LAST_CHNG_DTTM
, FRST_REG_EMPNO
, FRST_REG_DTTM
)
VALUES (
		 #{cdGroup}
	   , #{cdVal}
	   , #{cdNm}
	   , #{cdDesc}
	   , #{lnupSer}
	   , #{uzYn}
	   , #{vldStdd}
	   , #{vldEndt}
	   , #{lastChngEmpno}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   , #{lastChngEmpno}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   )

mapper.delete:
/* 관리자 (코드관리:그룹삭제시 상세까직) 삭제 쿼리 (deleteCodeDetailByGroup)*/
DELETE
FROM ocuoc_ccdtl_l
WHERE CD_GROUP = #{cdGroup}

/* 관리자 (코드관리:그룹) 삭제 쿼리 (deleteGroupCode)*/
DELETE
FROM ocuoc_ccgrp_m
WHERE CD_GROUP = #{cdGroup}

/* 관리자 (코드관리:단일상세) 삭제 쿼리 (deleteCodeDetail)*/
DELETE
FROM ocuoc_ccdtl_l
WHERE CD_GROUP = #{cdGroup}
and CD_VAL = #{cdVal}

mapper.select:
/* 관리자 (코드관리:그룹) 총카운토 조회 쿼리 (groupCnt)*/
select count(*)
from ocuoc_ccgrp_m
where 1=1
  and CD_GROUP = #{cdGroup}
